<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {POINT_TASKS,createPointTaskPolicyApi,validPointPolicyBody} from '../../services/point-task-policies.js'
import {createPointPolicyRecovery} from '../../services/point-policy-recovery.js'
import {couponLocalTime,couponUtcTime} from '../../services/coupons.js'
import {imageRequestKey} from '../../services/private-images.js'
const state=reactive(initialDiagnosisState()),editing=ref(0),types=Object.keys(POINT_TASKS),fresh=()=>({type:'CHECK_IN',points:'',note:'',fromDate:'',fromTime:'',toDate:'',toTime:'',revision:0}),form=reactive(fresh()),api=createPointTaskPolicyApi()
const allowed=()=>operatorSession.canPoints,recovery=createPointPolicyRecovery({actor:()=>operatorSession.actorId})
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=> 'point-task-policy',recovery,newKey:imageRequestKey,load:api.list,write:api.write,onWritten:clearForm,confirm:action=>new Promise(resolve=>uni.showModal({title:action==='discard-local'?'清理本机原请求':'确认积分任务规则',content:action==='discard-local'?'请核对刚读取的服务器列表。确认只清理本机恢复记录，不删除服务器政策，不自动重发。':'来源、积分和有效期须可核对。发布后条款冻结，同一任务只能有一条发布政策；配置不会给任何账号发放积分。确认的原请求会保存在本机用于断线恢复。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}))})
let visible=false
function clearForm(){editing.value=0;Object.assign(form,fresh())}
function edit(p){if(state.busy||state.retry||state.kind==='storage')return;editing.value=p.id;Object.assign(form,{type:p.task_type,points:String(p.points),note:p.source_note,revision:p.revision});[form.fromDate,form.fromTime]=couponLocalTime(p.valid_from).split(' ');[form.toDate,form.toTime]=couponLocalTime(p.valid_to).split(' ')}
function save(){const from=couponUtcTime(form.fromDate,form.fromTime),to=couponUtcTime(form.toDate,form.toTime);if(!/^[1-9]\d{0,6}$/.test(form.points)||Number(form.points)>1000000||!from||!to||Date.parse(to)<=Date.parse(from)||form.note.trim().length<2){state.message='请填写正整数积分、可核对的来源及有效时间。';return}const action=editing.value?'update':'create',body={task_type:form.type,points:Number(form.points),source_note:form.note.trim(),valid_from:from,valid_to:to,...(editing.value?{expected_revision:form.revision}:{})};if(!validPointPolicyBody(body,action)){state.message='积分规则内容无效，请检查来源、分值及时间。';return}flow.save(action,editing.value,body)}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function reset(){flow.reset();clearForm()}
watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k))clearForm()})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
</script>
<template><view class="reservation-page"><text class="reservation-title">积分任务规则</text><text>独立积分管理权限。分值须有来源，不使用页面示例作为正式规则；配置本身不发放积分，实际到账以车主任务和流水为准。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有积分规则权限。</text><template v-else><view class="reservation-panel"><text>{{editing?'修改任务草稿':'新建任务草稿'}}</text><picker :range="types.map(t=>POINT_TASKS[t])" :value="types.indexOf(form.type)" :disabled="state.busy||state.retry||state.kind==='storage'" @change="form.type=types[Number($event.detail.value)]"><view>{{POINT_TASKS[form.type]}}</view></picker><text>{{form.type==='CHECK_IN'?'北京时间每日一次':'每账号终身一次，换版不重发'}}</text><input v-model="form.points" type="number" maxlength="7" :disabled="state.busy||state.retry||state.kind==='storage'" placeholder="配置积分 1–1000000"/><input v-model="form.note" maxlength="256" :disabled="state.busy||state.retry||state.kind==='storage'" placeholder="来源说明 2–256 字"/><text>北京时间生效 / 截止</text><input v-model="form.fromDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.fromTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/><input v-model="form.toDate" :disabled="state.busy||state.retry" placeholder="YYYY-MM-DD"/><input v-model="form.toTime" :disabled="state.busy||state.retry" placeholder="HH:mm"/><button :disabled="state.busy||state.retry||state.kind==='storage'" @tap="save">保存任务草稿</button><button :disabled="state.busy||state.retry||state.kind==='storage'" @tap="clearForm">新建另一草稿</button></view><text v-if="state.message">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机原请求</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新当前规则</button><template v-if="state.data"><text v-if="!state.data.items.length">尚未配置积分任务。缺少规则的任务为未知。</text><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text>规则 #{{p.id}} · {{POINT_TASKS[p.task_type]}} · {{p.status}} · 版本 {{p.revision}}</text><text>{{p.points}} 积分 · {{p.frequency==='DAILY'?'北京自然日一次':'每账号一次'}}</text><text>{{p.source_note}}</text><text>{{couponLocalTime(p.valid_from)}} 至 {{couponLocalTime(p.valid_to)}}</text><button v-if="p.status==='DRAFT'" :disabled="state.busy||state.retry||state.kind==='storage'" @tap="edit(p)">修改草稿</button><button v-if="p.status==='DRAFT'" :disabled="state.busy||state.retry||state.kind==='storage'" @tap="flow.save('status',p.id,{expected_revision:p.revision,status:'PUBLISHED'})">发布并冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="state.busy||state.retry||state.kind==='storage'" @tap="flow.save('status',p.id,{expected_revision:p.revision,status:'STOPPED'})">停止政策</button></view><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页</button><button v-if="state.page*20<state.data.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页</button></template></template><button @tap="uni.navigateTo({url:'/pages/operator/review'})">运营工作区</button></view></template>
